class Node:
    def __init__(self):
        self.left = None
        self.right = None
        self.leftCnt = 0
        self.rightCnt = 0

    def add_left(self):
        if self.left is None:
            self.left = Node()
            self.leftCnt = 1
        else:
            self.leftCnt += 1

    def add_right(self):
        if self.right is None:
            self.right = Node()
            self.rightCnt = 1
        else:
            self.rightCnt += 1

    def rem_left(self):
        self.leftCnt -= 1

    def rem_right(self):
        self.rightCnt -= 1

    def has_left(self):
        return self.left is not None and self.leftCnt > 0

    def has_right(self):
        return self.right is not None and self.rightCnt > 0

def insert(u, num, dig=MAX_BIT):
    if dig < 0:
        return
    b = (num >> dig) & 1
    if b:
        u.add_right()
        insert(u.right, num, dig-1)
    else:
        u.add_left()
        insert(u.left, num, dig-1)

